INSERT INTO parks (name, lat, lon, region) SELECT 'Gyeongju World', 35.837, 129.283, 'South Korea' WHERE NOT EXISTS (SELECT 1 FROM parks WHERE name = 'Gyeongju World');
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, yr, opened, openedPrec, closed, closedPrec, laps) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Draken', 'Gyeongju World', 'Steel', 'Bolliger & Mabillard', 'B&M Dive', 206.7, NULL, NULL, 2, NULL, 2018, '2018-05-01', 'day', NULL, NULL, 1 WHERE NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Draken' AND park = 'Gyeongju World');
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_added', c.name, NULL, json_object('id', c.id, 'park', c.park) FROM coasters c WHERE c.name = 'Draken' AND c.park = 'Gyeongju World' AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'coaster_added' AND json_extract(a.detail, '$.id') = c.id);
